// arlongSkins.js — Arlong's 14 alt skins (cosmetic only). The sheets are generated by
// tools/arlong_build/gen_arlong_skins.py as `<sheet>__<tag>.png`. This module REGISTERS the skins into skins.js
// SKINS.arlong at load (so the shared skins.js table is untouched), exposes the tagged anim sets used by Arlong's
// own win2 / idle-flex swaps, and the per-skin WATER THEME the renderer uses for zones, the flood, splashes and
// particles (lava for Magma, a nebula for Alien X …). Nothing here is read by the simulation.
import { SKINS } from './skins.js'
import { arlong as ARLONG_CHAR, arlongSkinSet } from './arlongData.js'
export { arlongSkinSet }

// tag → display name. `arlongAlienX` keeps the engine's generic Alien X starfield overlay (skin id ends "AlienX").
export const ARLONG_SKIN_LIST = [
  ['hody', 'Energy Steroid (Hody)'], ['tiger', 'Sun Pirates (Fisher Tiger)'], ['jinbe', 'Knight of the Sea (Jinbe)'],
  ['reef', 'Coral Reef'], ['abyss', 'Anglerfish Abyss'], ['magma', 'Magma Shark'], ['frost', 'Glacier Shark'],
  ['gilded', 'Golden Gill Emperor'], ['phantom', 'Phantom of Arlong Park'], ['neon', 'Neon Grand Line'],
  ['cafe', 'Mermaid Café Glitter'], ['ben10', 'Ben 10'], ['albedo', 'Albedo'], ['alienx', 'Alien X'],
]
export const arlongSkinId = tag => tag === 'alienx' ? 'arlongAlienX' : `arlong_${tag}`
const retag = (p, tag) => p.replace(/\.png$/i, `__${tag}.png`)

export const arlongFxSheet = (sheet, tag) => (tag && sheet ? retag(sheet, tag) : sheet)

// Register into SKINS.arlong (idempotent).
const list = SKINS.arlong || (SKINS.arlong = [{ id: 'default', name: 'Default', unlockLevel: 0, portrait: ARLONG_CHAR.portrait, spriteScale: ARLONG_CHAR.spriteScale, animationData: null }])
for (const [tag, name] of ARLONG_SKIN_LIST) {
  const id = arlongSkinId(tag)
  if (list.some(s => s.id === id)) continue
  list.push({ id, name, unlockLevel: 0, portrait: retag(ARLONG_CHAR.portrait, tag), spriteScale: ARLONG_CHAR.spriteScale,
    animationData: arlongSkinSet(ARLONG_CHAR.animationData, tag), recolorTag: tag })
}

// ── WATER THEMES (render-only). Colours are [r, g, b]. `fx` = extra particle personality of the pools:
//   embers (rise + flicker) · motes (slow bioluminescent drift) · frost (sparkle crystals) · wisps (ghost trails)
//   · bubbles · stars (twinkling starfield + constellation lines) · grid (synthwave scanlines) · glitter
const C = (r, g, b) => [r, g, b]
export const ARLONG_WATER = {
  _:       { top: C(130, 160, 255), bot: C(40, 60, 190), ripple: C(210, 225, 255), flood: C(40, 70, 190), foam: C(200, 220, 255), fx: 'bubbles' },
  hody:    { top: C(200, 30, 50), bot: C(70, 0, 12), ripple: C(255, 140, 150), flood: C(110, 0, 20), foam: C(255, 190, 195), fx: 'bubbles' },
  tiger:   { top: C(255, 190, 70), bot: C(230, 80, 20), ripple: C(255, 240, 190), flood: C(240, 110, 30), foam: C(255, 235, 180), fx: 'glitter' },
  jinbe:   { top: C(90, 240, 220), bot: C(10, 120, 140), ripple: C(215, 255, 250), flood: C(20, 140, 150), foam: C(210, 255, 248), fx: 'bubbles' },
  reef:    { top: C(80, 235, 225), bot: C(255, 90, 170), ripple: C(255, 210, 235), flood: C(40, 190, 190), foam: C(255, 215, 235), fx: 'bubbles' },
  abyss:   { top: C(20, 30, 80), bot: C(2, 4, 18), ripple: C(80, 255, 240), flood: C(4, 8, 30), foam: C(120, 255, 240), fx: 'motes' },
  magma:   { top: C(255, 170, 30), bot: C(170, 20, 0), ripple: C(255, 240, 140), flood: C(200, 40, 0), foam: C(255, 220, 100), fx: 'embers' },
  frost:   { top: C(225, 245, 255), bot: C(120, 180, 230), ripple: C(255, 255, 255), flood: C(150, 205, 240), foam: C(240, 250, 255), fx: 'frost' },
  gilded:  { top: C(255, 230, 110), bot: C(190, 120, 10), ripple: C(255, 250, 210), flood: C(210, 150, 20), foam: C(255, 245, 190), fx: 'glitter' },
  phantom: { top: C(140, 255, 170), bot: C(10, 90, 60), ripple: C(200, 255, 215), flood: C(30, 140, 90), foam: C(200, 255, 215), fx: 'wisps' },
  neon:    { top: C(255, 60, 220), bot: C(40, 10, 120), ripple: C(60, 255, 255), flood: C(120, 20, 170), foam: C(120, 255, 255), fx: 'grid' },
  ben10:   { top: C(120, 255, 90), bot: C(10, 110, 20), ripple: C(210, 255, 200), flood: C(20, 140, 30), foam: C(200, 255, 190), fx: 'bubbles' },
  cafe:    { top: C(255, 150, 210), bot: C(200, 40, 140), ripple: C(255, 235, 248), flood: C(230, 80, 170), foam: C(255, 225, 240), fx: 'glitter' },   // Mermaid Café: pink glitter
  albedo:  { top: C(255, 90, 90), bot: C(90, 0, 0), ripple: C(255, 220, 220), flood: C(130, 10, 10), foam: C(255, 215, 215), fx: 'bubbles' },
  alienx:  { top: C(150, 60, 220), bot: C(8, 4, 30), ripple: C(255, 255, 255), flood: C(30, 10, 70), foam: C(235, 240, 255), fx: 'stars', nebula: [C(255, 60, 200), C(80, 140, 255), C(120, 255, 170)] },
}
export const arlongWater = tag => ARLONG_WATER[tag] || ARLONG_WATER._
